mapper.select:
SELECT id, trace_id AS traceId, module, exception_class AS exceptionClass, message, request_method AS requestMethod, request_path AS requestPath, user_id AS userId, operator, client_ip AS clientIp, created_at AS createdAt FROM error_log WHERE created_at >= #{from} AND created_at < #{to}
AND module = #{module}
AND CONCAT_WS(' ', exception_class, message, trace_id, operator) LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM error_log
WHERE created_at >= #{from}
  AND created_at < #{to}

    AND module = #{module}


    AND CONCAT_WS(' ', exception_class, message, trace_id, operator)
        LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'
